<section class="container page-section narrow-page"><div class="breadcrumbs"><a href="/">Home</a><span>/</span><a href="/cart">Cart</a><span>/</span><span>Checkout</span></div><span class="eyebrow">ALMOST THERE</span><h1>Checkout</h1><p class="page-intro">Confirm your delivery details. This starter uses a demo order flow, not a real payment processor.</p><div class="checkout-layout"><form method="post" action="/checkout" class="checkout-form"><?= csrf_field() ?><h2>Delivery information</h2><label>Full name<input name="shipping_name" required maxlength="120" value="<?= e(current_user()['name']) ?>" autocomplete="name"></label><label>Email address<input type="email" name="shipping_email" required value="<?= e(current_user()['email']) ?>" autocomplete="email"></label><label>Shipping address<textarea name="shipping_address" required minlength="8" rows="4" placeholder="Street, city, state, postal code"></textarea></label><div class="demo-payment"><span>◎</span><div><strong>Demo payment</strong><p>No card details are collected. Connect a payment gateway before accepting real orders.</p></div></div><button class="btn btn-primary btn-block">Place demo order <span>→</span></button></form><aside class="order-summary"><h2>Your order</h2><?php foreach($items as $item): ?><div class="checkout-item"><img src="<?= e(product_image($item)) ?>" alt=""><div><strong><?= e($item['name']) ?></strong><small>Qty <?= (int)$item['quantity'] ?></small></div><span><?= money($item['price']*$item['quantity']) ?></span></div><?php endforeach; ?><div class="summary-line"><span>Subtotal</span><strong><?= money($subtotal) ?></strong></div><div class="summary-line"><span>Shipping</span><span><?= $subtotal>=75?'FREE':money(5.99) ?></span></div><div class="summary-line"><span>Estimated tax (8%)</span><span><?= money($subtotal*.08) ?></span></div><div class="summary-total"><span>Total</span><strong><?= money($subtotal+($subtotal>=75?0:5.99)+round($subtotal*.08,2)) ?></strong></div></aside></div></section>